const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
const h = $input.first().json.headers;
const body = $input.first().json.body;
// Body dikirim API sebagai JSON.stringify; stringify ulang hasil parse menghasilkan byte yang sama.
const raw = JSON.stringify(body);
const ts = h['x-nomadia-timestamp'];
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const got = String(h['x-nomadia-signature'] || '');
const fresh = Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const same = got.length === expected.length && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected));
if (!fresh || !same) throw new Error('Tanda tangan tidak valid atau kedaluwarsa');
return [{ json: { deliveryId: body.id, order: body.data.order } }];

const o = $input.first().json.order;
const rp = (n) => 'Rp' + n.toLocaleString('id-ID');
const lines = o.items.map((i) => `- ${i.name} x${i.qty}: ${rp(i.unitPrice * i.qty)}`).join('
');
return [{ json: {
  to: o.customerEmail,
  subject: `Pembayaran diterima - pesanan ${o.id}`,
  text: `Halo ${o.customerName},

Pembayaran pesanan ${o.id} sebesar ${rp(o.total)} sudah kami terima.

${lines}

QR eSIM / info pengiriman menyusul di email berikutnya.

Salam,
Nomadia`,
  orderId: o.id
} }];
